Creating a Clustered Index:Now, we’ll create a clustered index on the Sale_Date column. This will organize the rows of the Sales table physically based on the sale date.
CREATE CLUSTERED INDEX idx_sale_date ON Sales (Sale_Date);
CREATE TABLE Sales (
Sale_ID INT PRIMARY KEY,
Sale_Date DATE,
Amount DECIMAL(10, 2),
Customer_ID INT
);
INSERT INTO Sales (Sale_ID, Sale_Date, Amount, Customer_ID)
VALUES
(1, '2024-10-01', 100.00, 101),
(2, '2024-10-03', 150.00, 102),
(3, '2024-10-02', 200.00, 101);
After executing the above, the data is stored in the following order:
SELECT * FROM Sales WHERE Sale_Date BETWEEN '2024-10-01' AND '2024-10-02';

Data Control Language (DCL) – Security & Access Control
Used to control user access and security within the database
GRANT SELECT, INSERT ON Employees TO User1;
REVOKE INSERT ON Employees FROM User1;

Data Definition Language (DDL) – Structure Definition
Used to define, modify, and delete database objects like tables, indexes, and schemas. Operates at the physical database structure level.
CREATE TABLE Employees (EmpID INT, Name VARCHAR(100));
ALTER TABLE Employees ADD Salary DECIMAL(10,2);
DROP TABLE Employees;

Data Manipulation Language (DML) – Work with Data
Used to retrieve and modify data stored inside tables.
INSERT INTO Employees VALUES (1, 'Ali');
SELECT * FROM Employees;
UPDATE Employees SET Name = 'Ali Ahmed' WHERE EmpID = 1;
DELETE FROM Employees WHERE EmpID = 1;

#include <windows.h>
#include <sql.h>
#include <sqlext.h>
#include <iostream>
int main() {
SQLHENV hEnv;
SQLHDBC hDbc;
SQLHSTMT hStmt;
SQLRETURN ret;
// Allocate environment handle
SQLAllocHandle(SQL_HANDLE_ENV, SQL_NULL_HANDLE, &hEnv);
// Set the ODBC version environment attribute
SQLSetEnvAttr(hEnv, SQL_ATTR_ODBC_VERSION, (void*)SQL_OV_ODBC3, 0);
// Allocate connection handle
SQLAllocHandle(SQL_HANDLE_DBC, hEnv, &hDbc);
// Connect to database (replace DSN, user, password accordingly)
SQLConnect(hDbc, (SQLCHAR*)"DSN=mydsn", SQL_NTS, (SQLCHAR*)"username", SQL_NTS, (SQLCHAR*)"password", SQL_NTS);
// Allocate statement handle
SQLAllocHandle(SQL_HANDLE_STMT, hDbc, &hStmt);
// Execute an SQL query
SQLExecDirect(hStmt, (SQLCHAR*)"SELECT * FROM my_table", SQL_NTS);
// Fetch and display the data
SQLCHAR columnData[256];
while (SQLFetch(hStmt) == SQL_SUCCESS) {
SQLGetData(hStmt, 1, SQL_C_CHAR, columnData, sizeof(columnData), NULL);
std::cout << "Column Data: " << columnData << std::endl;
} // Clean up
SQLFreeHandle(SQL_HANDLE_STMT, hStmt);
SQLDisconnect(hDbc);
SQLFreeHandle(SQL_HANDLE_DBC, hDbc);
SQLFreeHandle(SQL_HANDLE_ENV, hEnv);
return 0; }

